//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error can be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry numbered from zero.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        if self.base_delay_ms >= self.max_delay_ms {
            return self.max_delay_ms;
        }

        let mut delay = self.base_delay_ms;
        for _ in 0..retry_number {
            delay = delay
                .checked_mul(2)
                .map_or(self.max_delay_ms, |next| next.min(self.max_delay_ms));
            if delay == self.max_delay_ms {
                break;
            }
        }
        delay
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_saturates_without_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };
        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);

        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX / 2 + 1,
            max_delay_ms: u64::MAX,
        };
        assert_eq!(config.delay_for_retry(1), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

//! Configurable retrying job execution.
mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempts - 1));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(5), &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_stop_without_sleeping() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(5), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(3), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("down".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` accepts a `RetryConfig` and retries only `RetryError::Transient`
failures. `RetryError::Permanent` failures are returned immediately. The
`max_attempts` setting is the total number of job calls, including the first
call. Retries wait with an exponential delay starting at `base_delay_ms`; the
delay doubles after each retry and saturates at `max_delay_ms`.

For example:

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 1_000,
};
let mut sleeper = FakeSleeper::default();
let result = run_job(&config, &mut sleeper, || {
    Err(RetryError::Transient("temporary failure".into()))
});
assert_eq!(result, Err(RetryError::Transient("temporary failure".into())));
assert_eq!(sleeper.sleeps, vec![100, 200, 400]);
```

A `max_attempts` value of zero is treated as one attempt so the job is always
called at least once.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_runner_retries_transient_failures() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 2,
        max_delay_ms: 3,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 | 2 => Err(RetryError::Transient("busy".to_owned())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![2, 3]);
}
